    (2, 4, 'Announcement', 'Statewide membership drive launched', 'மாநில அளவிலான உறுப்பினர் சேர்க்கை இயக்கம் தொடக்கம்', 'statewide-membership-drive-launched-musqsg4n', 'NMPI begins a statewide drive to enrol new members across all districts.', NULL, '<p>The movement has launched a statewide membership drive. Volunteers will visit every taluk to help citizens register and receive their digital ID card.</p>', NULL, '/uploads/IMG-20260925-WA0022.jpg', 0, 'PUBLISHED', '2026-10-04 00:15:30', '2026-10-04 00:15:30', '2026-10-04 00:15:30');

