--
-- Dumping data for table`organization_pages`
--

  INSERT INTO`tblOrganization_pages`(`id`, `page_key`, `title`, `title_ta`, `content`, `content_ta`, `updated_at`) VALUES
    (1, 'about', 'About the Movement', 'இயக்கம் பற்றி', '<p>Netaji Makkal Pathukappu Iyakkam is a disciplined people\'s movement inspired by the ideals of Netaji Subhas Chandra Bose, working for the rights, welfare and safety of the people of Tamil Nadu.</p>', '<p>நேதாஜி மக்கள் பாதுகாப்பு இயக்கம், நேதாஜி சுபாஷ் சந்திர போஸ் அவர்களின் கொள்கை வழியில் தமிழக மக்களின் உரிமைகள், நலன் மற்றும் பாதுகாப்பிற்காக செயல்படும் ஒழுக்கமிக்க மக்கள் இயக்கம்.</p>', '2026-10-04 00:03:56'),
    (2, 'history', 'Our History', 'இயக்க வரலாறு', '<p>From a small group of volunteers, the movement has grown into a structured organisation spanning every district of Tamil Nadu.</p>', '<p>சிறு தன்னார்வலர் குழுவாகத் தொடங்கிய இயக்கம், இன்று தமிழகத்தின் அனைத்து மாவட்டங்களிலும் பரந்து விரிந்த அமைப்பாக வளர்ந்துள்ளது.</p>', '2026-10-04 00:03:56'),
    (3, 'structure', 'Organisational Structure', 'அமைப்பு கட்டமைப்பு', '<p>State Executive Council, District Committees, Taluk / Block Divisions and Village Units.</p>', '<p>மாநில செயற்குழு, மாவட்ட குழுக்கள், ஒன்றிய / வட்ட பிரிவுகள் மற்றும் கிராம கிளைகள்.</p>', '2026-10-04 00:03:56');

